/// Gets the Line Break Class for a code point
pub fn getLineBreakClass(cp: Codepoint) LineBreakClass {
    if (cp > 0x10FFFF) return .XX;
    const block = @as(usize, cp >> 8);
    if (block >= lb_stage1.len) return .XX;
    const offset = @as(usize, cp & 0xFF);
    const stage2_idx = lb_stage1[block] + offset;
    if (stage2_idx >= lb_stage2.len) return .XX;
    return @enumFromInt(lb_stage2[stage2_idx]);
}
